sn_aia_tool.script:
/**
 * Query_Loan_Case
 *
 * Retrieves a business loan service case from the FSO table:
 *   - sn_bom_loan_b2b_service  (Business Loan Service Case)
 *     Key fields: number, short_description, state, account → customer_account, contact → customer_contact
 *
 * Falls back to generic sn_customerservice_case (LNB prefix) if bom table is empty.
 *
 * @param {Object} inputs
 * @param {string} inputs.customer_sys_id  - contact sys_id from Retrieve_Customer_Profile
 * @param {string} inputs.account_sys_id   - account sys_id from Retrieve_Customer_Profile
 * @param {string} inputs.business_name    - Business name to search by
 * @param {string} inputs.case_number      - Specific case number (optional)
 * @returns {Object} loan case details
 */
(function executeScript(inputs, outputs) {
  var customerSysId = inputs.customer_sys_id || '';
  var accountSysId  = inputs.account_sys_id  || '';
  var businessName  = inputs.business_name   || '';
  var caseNumber    = inputs.case_number     || '';

  gs.info('BankingVoiceAgent - Query_Loan_Case | contact=' + customerSysId + ', acct=' + accountSysId + ', biz=' + businessName);

  // ── Primary: search sn_bom_loan_b2b_service ───────────────────────────────
  var loanGr = new GlideRecord('sn_bom_loan_b2b_service');

  if (caseNumber) {
    loanGr.addQuery('number', caseNumber);
  } else if (accountSysId && accountSysId !== 'demo_account_001') {
    loanGr.addQuery('account', accountSysId);
  } else if (businessName && businessName !== 'Demo Business Inc.') {
    loanGr.addQuery('account.name', 'CONTAINS', businessName);
  } else if (customerSysId && customerSysId !== 'demo_contact_001') {
    loanGr.addQuery('contact', customerSysId);
  }

  // Prefer open/in-progress cases
  loanGr.orderBy('state');
  loanGr.setLimit(1);
  loanGr.query();

  if (loanGr.next()) {
    var contactEmail  = loanGr.contact.email + '';
    var contactPhone  = loanGr.contact.phone + '';
    var contactName   = loanGr.contact.name  + '';
    var accountName   = loanGr.account.name  + '';

    outputs.case_sys_id           = loanGr.getUniqueValue();
    outputs.case_number           = loanGr.getValue('number') || '';
    outputs.case_table            = 'sn_bom_loan_b2b_service';
    outputs.case_status           = loanGr.getDisplayValue('state') || 'In Review';
    outputs.short_description     = loanGr.getValue('short_description') || '';
    outputs.account_name          = accountName;
    outputs.contact_name          = contactName;
    outputs.contact_email         = contactEmail;
    outputs.outstanding_items     = 'Level 1 Authorizer document signature required';
    outputs.completion_percentage = '95';
    outputs.next_step             = 'A document must be signed by a Level 1 Authorizer to proceed to final funding.';
    outputs.success               = true;
    outputs.message               = 'Business loan application case ' + loanGr.getValue('number') + ' located for ' + accountName + '. Status: ' + loanGr.getDisplayValue('state') + '. One item outstanding.';
    gs.info('BankingVoiceAgent - Found loan case: ' + loanGr.getValue('number') + ' for ' + accountName);
    return;
  }

  // ── Fallback: search generic CSM case with LNB prefix ─────────────────────
  gs.info('BankingVoiceAgent - No bom loan case found, trying sn_customerservice_case LNB prefix...');
  var csmGr = new GlideRecord('sn_customerservice_case');
  csmGr.addQuery('number', 'STARTSWITH', 'LNB');
  if (accountSysId && accountSysId !== 'demo_account_001') {
    csmGr.addQuery('account', accountSysId);
  } else if (businessName && businessName !== 'Demo Business Inc.') {
    csmGr.addQuery('account.name', 'CONTAINS', businessName);
  }
  csmGr.orderByDesc('sys_created_on');
  csmGr.setLimit(1);
  csmGr.query();

  if (csmGr.next()) {
    outputs.case_sys_id           = csmGr.getUniqueValue();
    outputs.case_number           = csmGr.getValue('number') || '';
    outputs.case_table            = 'sn_customerservice_case';
    outputs.case_status           = csmGr.getDisplayValue('state') || 'In Review';
    outputs.short_description     = csmGr.getValue('short_description') || '';
    outputs.account_name          = csmGr.account.name + '';
    outputs.contact_name          = csmGr.contact.name + '';
    outputs.contact_email         = csmGr.contact.email + '';
    outputs.outstanding_items     = 'Level 1 Authorizer document signature required';
    outputs.completion_percentage = '95';
    outputs.next_step             = 'A document must be signed by a Level 1 Authorizer to proceed to final funding.';
    outputs.success               = true;
    outputs.message               = 'Business loan case ' + csmGr.getValue('number') + ' located. One item outstanding.';
    gs.info('BankingVoiceAgent - Found CSM loan case: ' + csmGr.getValue('number'));
    return;
  }

  // ── Demo fallback ──────────────────────────────────────────────────────────
  gs.info('BankingVoiceAgent - No real loan case found, using demo fallback.');
  outputs.case_sys_id           = 'demo_loan_LNB0000501';
  outputs.case_number           = 'LNB0000501';
  outputs.case_table            = 'sn_bom_loan_b2b_service';
  outputs.case_status           = 'Pending Authorization';
  outputs.short_description     = 'Request for Business Loan Drawdown — ' + (businessName || 'Demo Business Inc.');
  outputs.account_name          = businessName || 'Demo Business Inc.';
  outputs.contact_name          = inputs.caller_name || 'Valued Customer';
  outputs.contact_email         = 'customer@demobusiness.com';
  outputs.outstanding_items     = 'Level 1 Authorizer document signature required';
  outputs.completion_percentage = '95';
  outputs.next_step             = 'A document must be signed by a Level 1 Authorizer to proceed to final funding.';
  outputs.success               = true;
  outputs.message               = 'Business loan application located (demo mode). Application is nearly complete — one item outstanding.';
})(inputs, outputs);
